//! Contract of `zerodds-omg-security-main` with `zerodds-wire`
//! (internal/release/rc8-test-suite.md, "Crate tier").
//!
//! What this tool uses of `zerodds-wire`: the codec of `ShapeType`,
//! generated by `zerodds-build` from `interop/shapes/omg-dds-security.idl`
//! (`struct ShapeType { string<COLOR_MAX_LENGTH> color; //@key long x;
//! long y; long shapesize; }`, `COLOR_MAX_LENGTH = 64`, APPENDABLE by the
//! build script's `default_extensibility`) and `include!`d by
//! `src/shape_type.rs`. The generated `DdsType` methods open
//! `Writer::appending(Endianness::Little | Big, 4, out)` for XCDR2 and a cap
//! of 8 for XCDR1; the inherent codec writes `write_dheader`,
//! `write_string_bounded(color, 64)`, `write_i32` three times and
//! `finish_dheader`; the wrapper closes with `check_deferred` and `finish`
//! and truncates `out` on an error. The reader is `Reader::with_max_align`
//! with `read_dheader` + `position` as the end, `read_string`, `read_i32`
//! and `skip_to(end)`. The key holder is the colour written big endian with
//! a cap of 4 (XTypes 1.3 §7.6.8). The tool is a binary without a library,
//! so the contract makes these calls itself, in the generator's order.
//!
//! Oracle, octets written out by hand: DDS-XTypes 1.3 §7.4.1.1.1, §7.4.1.1.2,
//! §7.4.2 (DELIMITED_CDR for APPENDABLE under XCDR2; not delimited under
//! XCDR1), §7.4.3.4.1 (DHEADER), §7.6.8 (key holder big endian, MAXALIGN 4).
#![allow(clippy::unwrap_used)]

use zerodds_wire::{Endianness, Reader, WireError, Writer};

const COLOR_MAX_LENGTH: usize = 64;

#[derive(Debug, PartialEq)]
struct Shape {
    color: String,
    x: i32,
    y: i32,
    shapesize: i32,
}

fn sample() -> Shape {
    Shape {
        color: "BLUE".to_string(),
        x: 7,
        y: 14,
        shapesize: 30,
    }
}

/// The generated inherent `encode`.
fn write_shape(w: &mut Writer, s: &Shape, delimited: bool) -> Result<(), WireError> {
    let header = delimited.then(|| w.write_dheader());
    w.write_string_bounded(&s.color, COLOR_MAX_LENGTH)?;
    w.write_i32(s.x);
    w.write_i32(s.y);
    w.write_i32(s.shapesize);
    if let Some(header) = header {
        w.finish_dheader(header);
    }
    Ok(())
}

/// The generated `DdsType::encode`/`encode_be`/`encode_xcdr1`.
fn encode(
    s: &Shape,
    endianness: Endianness,
    max_align: usize,
    delimited: bool,
    out: &mut Vec<u8>,
) -> Result<(), WireError> {
    let start = out.len();
    let mut w = Writer::appending(endianness, max_align, core::mem::take(out));
    let written = write_shape(&mut w, s, delimited).and_then(|()| w.check_deferred());
    *out = w.finish();
    if written.is_err() {
        out.truncate(start);
    }
    written
}

fn decode(
    bytes: &[u8],
    endianness: Endianness,
    max_align: usize,
    delimited: bool,
) -> Result<Shape, WireError> {
    let mut r = Reader::with_max_align(bytes, endianness, max_align);
    let end = if delimited {
        Some(r.read_dheader()? + r.position())
    } else {
        None
    };
    let color = r.read_string()?;
    let x = r.read_i32()?;
    let y = r.read_i32()?;
    let shapesize = r.read_i32()?;
    if let Some(end) = end {
        r.skip_to(end)?;
    }
    Ok(Shape {
        color,
        x,
        y,
        shapesize,
    })
}

/// The sample under DELIMITED_CDR, little endian.
const APPENDABLE_LE: [u8; 28] = [
    0x18, 0x00, 0x00, 0x00, // DHEADER: 24
    0x05, 0x00, 0x00, 0x00, b'B', b'L', b'U', b'E', 0x00, // color, length counts the NUL
    0x00, 0x00, 0x00, // pad
    0x07, 0x00, 0x00, 0x00, // x
    0x0e, 0x00, 0x00, 0x00, // y
    0x1e, 0x00, 0x00, 0x00, // shapesize
];

#[test]
fn xtypes_7_4_2_the_shape_is_a_dheader_then_its_members_in_both_byte_orders() {
    let mut le = Vec::new();
    encode(&sample(), Endianness::Little, 4, true, &mut le).unwrap();
    assert_eq!(le, APPENDABLE_LE);
    let mut be = Vec::new();
    encode(&sample(), Endianness::Big, 4, true, &mut be).unwrap();
    assert_eq!(
        be,
        [
            0x00, 0x00, 0x00, 0x18, 0x00, 0x00, 0x00, 0x05, b'B', b'L', b'U', b'E', 0x00, 0x00,
            0x00, 0x00, 0x00, 0x00, 0x00, 0x07, 0x00, 0x00, 0x00, 0x0e, 0x00, 0x00, 0x00, 0x1e,
        ]
    );
    assert_ne!(le, be, "a big-endian body is not the little-endian one");
    assert_eq!(
        decode(&APPENDABLE_LE, Endianness::Little, 4, true).unwrap(),
        sample()
    );
    assert_eq!(decode(&be, Endianness::Big, 4, true).unwrap(), sample());
}

#[test]
fn xtypes_7_4_3_4_1_an_appending_writer_counts_alignment_from_where_out_ends() {
    let mut out = vec![0xee, 0xee];
    encode(&sample(), Endianness::Little, 4, true, &mut out).unwrap();
    assert_eq!(out[..2], [0xee, 0xee]);
    assert_eq!(out[2..], APPENDABLE_LE);
}

#[test]
fn xtypes_7_4_2_under_xcdr1_the_appendable_shape_has_no_dheader() {
    let mut out = Vec::new();
    encode(&sample(), Endianness::Little, 8, false, &mut out).unwrap();
    assert_eq!(out, APPENDABLE_LE[4..]);
    assert_eq!(
        decode(&APPENDABLE_LE[4..], Endianness::Little, 8, false).unwrap(),
        sample()
    );
}

#[test]
fn a_color_past_64_octets_is_refused_and_leaves_out_as_it_was() {
    let mut long = sample();
    long.color = "C".repeat(COLOR_MAX_LENGTH + 1);
    let mut out = vec![0x00, 0x09, 0x00, 0x00];
    assert!(encode(&long, Endianness::Little, 4, true, &mut out).is_err());
    assert_eq!(out, [0x00, 0x09, 0x00, 0x00]);
    long.color = "C".repeat(COLOR_MAX_LENGTH);
    let mut out = Vec::new();
    encode(&long, Endianness::Little, 4, true, &mut out).unwrap();
    assert_eq!(out[4..8], [65, 0, 0, 0]);
}

#[test]
fn a_sample_cut_short_or_with_a_dheader_past_its_end_is_an_error() {
    for cut in 0..APPENDABLE_LE.len() {
        assert!(
            decode(&APPENDABLE_LE[..cut], Endianness::Little, 4, true).is_err(),
            "cut at {cut}"
        );
    }
    let mut lying = APPENDABLE_LE.to_vec();
    lying[0] = 0x40;
    assert!(decode(&lying, Endianness::Little, 4, true).is_err());
}

#[test]
fn xtypes_7_6_8_the_key_holder_is_the_color_big_endian() {
    let mut w = Writer::with_max_align(Endianness::Big, 4);
    w.write_string_bounded("BLUE", COLOR_MAX_LENGTH).unwrap();
    assert_eq!(
        w.finish(),
        [0x00, 0x00, 0x00, 0x05, b'B', b'L', b'U', b'E', 0x00]
    );
}
